/**
 * Type definitions for image generation features
 * Used for outfit visualization and looks inspiration
 */

/**
 * Request payload for image generation API
 */
export interface ImageGenerationRequest {
  /** Description of the outfit to generate */
  description: string;

  /** Optional style parameters for image generation */
  style?: {
    /** Photography style (e.g., 'studio', 'lifestyle', 'flat-lay') */
    photographyStyle?: string;
    /** Mood or atmosphere (e.g., 'professional', 'casual', 'elegant') */
    mood?: string;
    /** Specific color palette preferences */
    colorPalette?: string[];
    /** Composition type (e.g., 'full-body', 'upper-body', 'flat-lay') */
    composition?: string;
  };

  /** User's session ID for tracking and rate limiting */
  sessionId?: string;
}

/**
 * Response from image generation API
 */
export interface ImageGenerationResponse {
  /** Success status */
  success: boolean;

  /** Generated image URL (if hosted externally) */
  imageUrl?: string;

  /** Base64 encoded image data (if returned inline) */
  imageBase64?: string;

  /** Original outfit description used for generation */
  description?: string;

  /** Error message if generation failed */
  error?: string;

  /** Additional metadata about the generation */
  metadata?: {
    /** Model used for generation */
    model: string;
    /** Generation timestamp */
    timestamp: string;
    /** Generation time in milliseconds */
    generationTime?: number;
    /** Tokens used (if applicable) */
    tokensUsed?: number;
  };
}

/**
 * Props for LooksInspiration component
 */
export interface LooksInspirationProps {
  /** Description of the outfit being visualized */
  outfitDescription: string;

  /** Generated image URL */
  imageUrl?: string;

  /** Base64 encoded image data */
  imageBase64?: string;

  /** Loading state */
  isLoading?: boolean;

  /** Error message if generation failed */
  error?: string;

  /** Callback when user requests to regenerate */
  onRegenerate?: () => void;

  /** Callback when user downloads the image */
  onDownload?: () => void;

  /** Additional CSS classes */
  className?: string;
}

/**
 * Internal state for image generation in chat
 */
export interface ImageGenerationState {
  /** Whether an image generation is in progress */
  isGenerating: boolean;

  /** Current outfit description being generated */
  currentDescription?: string;

  /** Generated images history in current session */
  generatedImages: Array<{
    description: string;
    imageUrl?: string;
    imageBase64?: string;
    timestamp: string;
  }>;

  /** Error state */
  error?: string;

  /** Retry count for failed generations */
  retryCount: number;
}

/**
 * Extended chat message type to support image responses
 */
export interface ChatMessageWithImage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;

  /** Image generation data if message includes visual content */
  imageData?: {
    description: string;
    imageUrl?: string;
    imageBase64?: string;
    isLoading?: boolean;
    error?: string;
  };
}

