   * @param description - Outfit description
   * @param options - Optional generation parameters
   * @returns Promise with image generation response
   */
  async generateOutfitImage(
    description: string,
    options?: {
      style?: string;
      occasion?: string;
      season?: string;
      photographyStyle?: string;
      composition?: string;
    }
  ): Promise<ImageGenerationResponse> {
    // Validate API key
    if (!this.apiKey) {
      return {
        success: false,
        error: 'OpenRouter API key not configured. Please set OPENROUTER_API_KEY environment variable.',
      };
    }

    // Check rate limiting
    if (!this.checkRateLimit()) {
      return {
        success: false,
        error: 'Rate limit exceeded. Please wait a moment before generating another image.',
      };
    }

    // Create enhanced fashion prompt
    const fashionPrompt = createFashionPrompt(description, {
      style: options?.style,
      occasion: options?.occasion,
      season: options?.season,
    });

    // Add additional composition guidance if provided
    let fullPrompt = fashionPrompt;
    if (options?.photographyStyle) {
      fullPrompt += `, ${options.photographyStyle} photography`;
    }
    if (options?.composition) {
      fullPrompt += `, ${options.composition} composition`;
    }

    const startTime = Date.now();

    try {
      // Attempt generation with retry logic
      let lastError: Error | null = null;

      for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
        try {
          const response = await this.callOpenRouterAPI(fullPrompt);
          const generationTime = Date.now() - startTime;

          this.logGeneration(true, fullPrompt, generationTime);

          return {
            success: true,
            imageUrl: response.imageUrl,
            imageBase64: response.imageBase64,
            description: description,
            metadata: {
              model: OPENROUTER_CONFIG.model,
              timestamp: new Date().toISOString(),
              generationTime,
              tokensUsed: response.tokensUsed,
            },
          };
        } catch (error) {
          lastError = error as Error;
          console.error(`Generation attempt ${attempt + 1} failed:`, error);

          // Don't retry on auth errors
          if (error instanceof Error && error.message.includes('API key')) {
            break;
          }

          // Wait before retrying (exponential backoff)
          if (attempt < OPENROUTER_CONFIG.maxRetries) {
            await this.delay(1000 * Math.pow(2, attempt));
          }
