/**
 * LooksInspiration Component
 * Displays generated outfit visualization images in chat
 */

'use client';

import React, { useState } from 'react';
import Image from 'next/image';
import { LooksInspirationProps } from '@/lib/types/image-types';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Skeleton } from '@/components/ui/skeleton';
import { Download, RefreshCw, Maximize2, AlertCircle } from 'lucide-react';

export function LooksInspiration({
  outfitDescription,
  imageUrl,
  imageBase64,
  isLoading = false,
  error,
  onRegenerate,
  onDownload,
  className = '',
}: LooksInspirationProps) {
  const [isZoomed, setIsZoomed] = useState(false);
  const [imageError, setImageError] = useState(false);

  // Determine the image source (URL or base64)
  const imageSrc = imageUrl || imageBase64;

  /**
   * Handles image download
   */
  const handleDownload = async () => {
    if (!imageSrc) return;

    try {
      // For base64 images, create a download link
      if (imageBase64) {
        const link = document.createElement('a');
        link.href = imageBase64;
        link.download = `outfit-inspiration-${Date.now()}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      } else if (imageUrl) {
        // For URL images, fetch and download
        const response = await fetch(imageUrl);
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `outfit-inspiration-${Date.now()}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
      }

      onDownload?.();
    } catch (error) {
      console.error('Failed to download image:', error);
    }
  };

  /**
   * Renders loading state
   */
  if (isLoading) {
    return (
      <Card className={`w-full max-w-2xl ${className}`}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <span className="animate-pulse">🎨</span>
            <span>กำลังสร้างภาพ...</span>
          </CardTitle>
          <CardDescription>
            {outfitDescription.substring(0, 100)}
            {outfitDescription.length > 100 ? '...' : ''}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <Skeleton className="w-full aspect-[3/4] rounded-lg" />
            <div className="space-y-2">
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-4 w-3/4" />
            </div>
          </div>
        </CardContent>
        <CardFooter className="text-sm text-muted-foreground">
          ⏳ การสร้างภาพอาจใช้เวลา 5-30 วินาที กรุณารอสักครู่...
        </CardFooter>
      </Card>
    );
  }

  /**
   * Renders error state
   */
  if (error || imageError) {
    return (
      <Card className={`w-full max-w-2xl border-destructive ${className}`}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertCircle className="w-5 h-5" />
            <span>ไม่สามารถสร้างภาพได้</span>
          </CardTitle>
          <CardDescription>
            {outfitDescription.substring(0, 100)}
            {outfitDescription.length > 100 ? '...' : ''}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg bg-destructive/10 p-4 space-y-3">
            <p className="text-sm text-destructive">
              {error || 'เกิดข้อผิดพลาดในการโหลดภาพ'}
            </p>
            <p className="text-xs text-muted-foreground">
              💡 ลองใหม่อีกครั้ง หรือให้รายละเอียดชุดมากขึ้น
            </p>
          </div>
        </CardContent>
        {onRegenerate && (
          <CardFooter>
            <Button
              onClick={onRegenerate}
              variant="outline"
              className="w-full"
            >
              <RefreshCw className="w-4 h-4 mr-2" />
              ลองสร้างใหม่
            </Button>
          </CardFooter>
        )}
      </Card>
    );
  }

  /**
   * Renders success state with image
   */
  if (imageSrc) {
    return (
      <>
        <Card className={`w-full max-w-2xl ${className}`}>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              ✨ Looks Inspiration
            </CardTitle>
            <CardDescription>
              {outfitDescription}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="relative group">
              {/* Main image display */}
              <div className="relative w-full aspect-[3/4] rounded-lg overflow-hidden bg-muted">
                <Image
                  src={imageSrc}
                  alt={`Outfit visualization: ${outfitDescription}`}
                  fill
                  className="object-cover transition-transform group-hover:scale-105"
                  onError={() => setImageError(true)}
                  priority
                />

                {/* Zoom button overlay */}
                <button
                  onClick={() => setIsZoomed(true)}
                  className="absolute inset-0 bg-black/0 hover:bg-black/20 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100"
                  aria-label="Zoom image"
                >
                  <div className="bg-white/90 rounded-full p-3">
                    <Maximize2 className="w-6 h-6" />
                  </div>
                </button>
              </div>

              {/* Image caption */}
              <p className="mt-3 text-sm text-center text-muted-foreground italic">
                AI-generated fashion visualization
              </p>
            </div>
          </CardContent>
          <CardFooter className="flex gap-2 flex-wrap">
            {/* Download button */}
            <Button
              onClick={handleDownload}
              variant="outline"
              size="sm"
              className="flex-1"
            >
              <Download className="w-4 h-4 mr-2" />
              ดาวน์โหลด
            </Button>

            {/* Regenerate button */}
            {onRegenerate && (
              <Button
                onClick={onRegenerate}
                variant="outline"
                size="sm"
                className="flex-1"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                สร้างใหม่
              </Button>
            )}
          </CardFooter>
        </Card>

        {/* Zoomed view dialog */}
        <Dialog open={isZoomed} onOpenChange={setIsZoomed}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-auto">
            <DialogHeader>
              <DialogTitle>{outfitDescription}</DialogTitle>
            </DialogHeader>
            <div className="relative w-full aspect-[3/4] bg-muted rounded-lg overflow-hidden">
              <Image
                src={imageSrc}
                alt={`Outfit visualization: ${outfitDescription}`}
                fill
                className="object-contain"
                priority
              />
            </div>
            <div className="flex gap-2 justify-end mt-4">
              <Button onClick={handleDownload} variant="outline">
                <Download className="w-4 h-4 mr-2" />
                ดาวน์โหลด
              </Button>
              <Button onClick={() => setIsZoomed(false)}>
                ปิด
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </>
    );
  }

  // Fallback: no image or loading state
  return null;
}

/**
 * LooksInspirationSkeleton - Loading placeholder
 */
export function LooksInspirationSkeleton() {
  return (
    <Card className="w-full max-w-2xl">
      <CardHeader>
        <Skeleton className="h-6 w-48" />
        <Skeleton className="h-4 w-full mt-2" />
      </CardHeader>
      <CardContent>
        <Skeleton className="w-full aspect-[3/4] rounded-lg" />
      </CardContent>
      <CardFooter>
        <Skeleton className="h-10 w-full" />
      </CardFooter>
    </Card>
  );
}

