/**
 * Image Generation API Route
 * POST endpoint for generating outfit visualization images
 */

import { NextRequest, NextResponse } from 'next/server';
import { generateOutfitImage } from '@/lib/services/image-generation-service';
import { ImageGenerationRequest, ImageGenerationResponse } from '@/lib/types/image-types';

/**
 * Rate limiting tracking (server-side)
 * In production, use Redis or similar for distributed rate limiting
 */
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();

/**
 * Rate limit configuration
 */
const RATE_LIMIT = {
  maxRequests: 10, // Max requests per window
  windowMs: 60000, // 1 minute window
};

/**
 * Checks rate limit for given IP address
 * @param ip - Client IP address
 * @returns true if request allowed, false if rate limited
 */
function checkRateLimit(ip: string): boolean {
  const now = Date.now();
  const limitData = rateLimitMap.get(ip);

  if (!limitData || now > limitData.resetTime) {
    // New window or expired window
    rateLimitMap.set(ip, {
      count: 1,
      resetTime: now + RATE_LIMIT.windowMs,
    });
    return true;
  }

  if (limitData.count >= RATE_LIMIT.maxRequests) {
    return false;
  }

  limitData.count++;
  return true;
}

/**
 * Gets client IP from request
 * @param request - Next.js request
 * @returns Client IP address
 */
function getClientIP(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  const realIp = request.headers.get('x-real-ip');
  return forwarded?.split(',')[0] || realIp || 'unknown';
}

/**
 * POST /api/generate-image
 * Generates outfit visualization image
 */
export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    // Check API key configuration
    if (!process.env.OPENROUTER_API_KEY) {
      console.warn('[Image Generation API] OPENROUTER_API_KEY not configured');
      return NextResponse.json(
        {
          success: false,
          error: 'Image generation service is not configured. Please contact support.',
        } as ImageGenerationResponse,
        { status: 503 }
      );
    }

    // Rate limiting check
    const clientIP = getClientIP(request);
    if (!checkRateLimit(clientIP)) {
      console.warn('[Image Generation API] Rate limit exceeded for IP:', clientIP);
      return NextResponse.json(
        {
          success: false,
          error: 'Too many requests. Please wait a moment before trying again.',
        } as ImageGenerationResponse,
        { status: 429 }
      );
    }

    // Parse request body
    let body: ImageGenerationRequest;
    try {
      body = await request.json();
    } catch (error) {
      return NextResponse.json(
        {
          success: false,
          error: 'Invalid request body. Expected JSON.',
        } as ImageGenerationResponse,
        { status: 400 }
      );
    }

    // Validate required fields
    if (!body.description || typeof body.description !== 'string') {
      return NextResponse.json(
        {
          success: false,
          error: 'Missing or invalid "description" field.',
        } as ImageGenerationResponse,
        { status: 400 }
      );
    }

    // Validate description length
    if (body.description.length < 10) {
      return NextResponse.json(
        {
          success: false,
          error: 'Description too short. Please provide more details about the outfit.',
        } as ImageGenerationResponse,
        { status: 400 }
      );
    }

    if (body.description.length > 1000) {
      return NextResponse.json(
        {
          success: false,
          error: 'Description too long. Please limit to 1000 characters.',
        } as ImageGenerationResponse,
        { status: 400 }
      );
    }

    // Log request
    console.log('[Image Generation API] Request received:', {
      ip: clientIP,
      descriptionLength: body.description.length,
      hasStyle: !!body.style,
      sessionId: body.sessionId,
    });

    // Generate image
    const response = await generateOutfitImage(body.description, {
      style: body.style?.photographyStyle,
      occasion: body.style?.mood,
      composition: body.style?.composition,
    });

    // Log response
    const duration = Date.now() - startTime;
    console.log('[Image Generation API] Response:', {
      success: response.success,
      hasImageUrl: !!response.imageUrl,
      hasImageBase64: !!response.imageBase64,
      duration: `${duration}ms`,
      error: response.error,
    });

    // Return appropriate status code based on success
    const statusCode = response.success ? 200 : 500;

    return NextResponse.json(response, {
      status: statusCode,
      headers: {
        'Content-Type': 'application/json',
        // CORS headers for cross-origin requests
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      },
    });
  } catch (error) {
    // Unexpected error
    const duration = Date.now() - startTime;
    console.error('[Image Generation API] Unexpected error:', error);
    console.error('[Image Generation API] Error details:', {
      duration: `${duration}ms`,
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
      errorStack: error instanceof Error ? error.stack : undefined,
    });

    return NextResponse.json(
      {
        success: false,
        error: 'An unexpected error occurred. Please try again later.',
      } as ImageGenerationResponse,
      { status: 500 }
    );
  }
}

/**
 * OPTIONS /api/generate-image
 * CORS preflight handler
 */
export async function OPTIONS() {
  return NextResponse.json(
    {},
    {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      },
    }
  );
}

/**
 * Clean up expired rate limit entries periodically
 */
setInterval(() => {
  const now = Date.now();
  const expiredKeys: string[] = [];

  rateLimitMap.forEach((value, key) => {
    if (now > value.resetTime) {
      expiredKeys.push(key);
    }
  });

  expiredKeys.forEach((key) => rateLimitMap.delete(key));

  if (expiredKeys.length > 0) {
    console.log(`[Image Generation API] Cleaned up ${expiredKeys.length} expired rate limit entries`);
  }
}, 60000); // Run every minute

